<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Expense Tracker</title>
<style>
  :root {
    --bg: #f5f6f8;
    --card: #ffffff;
    --line: #dfe3e8;
    --ink: #1d2129;
    --muted: #6b7280;
    --accent: #2563eb;
    --danger: #b91c1c;
  }
  * { box-sizing: border-box; }
  body {
    margin: 0;
    padding: 24px 16px 64px;
    background: var(--bg);
    color: var(--ink);
    font: 15px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  }
  .wrap { max-width: 880px; margin: 0 auto; }
  h1 { font-size: 22px; margin: 0 0 16px; }
  h2 { font-size: 15px; margin: 0 0 10px; text-transform: uppercase; letter-spacing: .04em; color: var(--muted); }
  .card {
    background: var(--card);
    border: 1px solid var(--line);
    border-radius: 10px;
    padding: 16px;
    margin-bottom: 16px;
  }
  .grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(150px, 1fr));
    gap: 12px;
  }
  label { display: block; font-size: 12px; color: var(--muted); margin-bottom: 4px; }
  input, select, button {
    font: inherit;
    width: 100%;
    padding: 8px 10px;
    border: 1px solid var(--line);
    border-radius: 6px;
    background: #fff;
    color: var(--ink);
  }
  button { cursor: pointer; }
  #add-expense {
    background: var(--accent);
    border-color: var(--accent);
    color: #fff;
    font-weight: 600;
  }
  #add-expense:hover { filter: brightness(1.08); }
  .actions { display: flex; align-items: flex-end; gap: 10px; margin-top: 12px; }
  .actions button { width: auto; padding: 8px 18px; }
  #form-error {
    color: var(--danger);
    font-size: 13px;
    min-height: 18px;
    margin-top: 10px;
  }
  #form-error:empty { margin-top: 0; }
  table { width: 100%; border-collapse: collapse; }
  th, td { text-align: left; padding: 8px 6px; border-bottom: 1px solid var(--line); }
  th { font-size: 12px; color: var(--muted); text-transform: uppercase; letter-spacing: .04em; }
  td.amt, th.amt { text-align: right; font-variant-numeric: tabular-nums; }
  .expense td { vertical-align: middle; }
  .exp-del {
    width: auto;
    padding: 4px 10px;
    font-size: 12px;
    color: var(--danger);
    border-color: var(--line);
  }
  .exp-del:hover { background: #fee2e2; }
  .cat { display: inline-block; padding: 2px 8px; border-radius: 999px; background: #eef2ff; font-size: 12px; }
  .note { color: var(--muted); font-size: 13px; }
  .totalbar {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    margin-bottom: 12px;
  }
  #total { font-size: 26px; font-weight: 700; font-variant-numeric: tabular-nums; }
  .cats { display: flex; flex-wrap: wrap; gap: 8px; }
  .cat-total {
    border: 1px solid var(--line);
    border-radius: 8px;
    padding: 6px 12px;
    font-size: 13px;
    background: #fafbfc;
  }
  .empty { color: var(--muted); padding: 12px 6px; }
</style>
</head>
<body>
<div class="wrap">
  <h1>Personal Expense Tracker</h1>

  <div class="card">
    <h2>Add expense</h2>
    <form id="expense-form" novalidate>
      <div class="grid">
        <div>
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" placeholder="0.00">
        </div>
        <div>
          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">groceries</option>
            <option value="transport">transport</option>
            <option value="bills">bills</option>
            <option value="fun">fun</option>
          </select>
        </div>
        <div>
          <label for="date">Date</label>
          <input type="date" id="date">
        </div>
        <div>
          <label for="note">Note (optional)</label>
          <input type="text" id="note" placeholder="e.g. weekly shop">
        </div>
      </div>
      <div class="actions">
        <button type="submit" id="add-expense">Add expense</button>
      </div>
      <div id="form-error" role="alert"></div>
    </form>
  </div>

  <div class="card">
    <h2>Filters</h2>
    <div class="grid">
      <div>
        <label for="filter-category">Category</label>
        <select id="filter-category">
          <option value="all">all</option>
          <option value="groceries">groceries</option>
          <option value="transport">transport</option>
          <option value="bills">bills</option>
          <option value="fun">fun</option>
        </select>
      </div>
      <div>
        <label for="filter-from">From</label>
        <input type="date" id="filter-from">
      </div>
      <div>
        <label for="filter-to">To</label>
        <input type="date" id="filter-to">
      </div>
      <div class="actions" style="margin:0">
        <button type="button" id="clear-filters">Clear filters</button>
      </div>
    </div>
  </div>

  <div class="card">
    <div class="totalbar">
      <h2 style="margin:0">Total (visible)</h2>
      <span id="total">0.00</span>
    </div>
    <div class="cats" id="cat-totals"></div>
  </div>

  <div class="card">
    <h2>Expenses</h2>
    <table>
      <thead>
        <tr>
          <th class="amt">Amount</th>
          <th>Category</th>
          <th>Date</th>
          <th>Note</th>
          <th></th>
        </tr>
      </thead>
      <tbody id="expense-list"></tbody>
    </table>
    <div class="empty" id="empty-msg" hidden>No expenses to show.</div>
  </div>
</div>

<script>
(function () {
  "use strict";

  var CATEGORIES = ["groceries", "transport", "bills", "fun"];
  var STORAGE_KEY = "expense-tracker.expenses.v1";

  var form = document.getElementById("expense-form");
  var amountEl = document.getElementById("amount");
  var categoryEl = document.getElementById("category");
  var dateEl = document.getElementById("date");
  var noteEl = document.getElementById("note");
  var errorEl = document.getElementById("form-error");

  var filterCatEl = document.getElementById("filter-category");
  var filterFromEl = document.getElementById("filter-from");
  var filterToEl = document.getElementById("filter-to");
  var clearFiltersEl = document.getElementById("clear-filters");

  var listEl = document.getElementById("expense-list");
  var emptyEl = document.getElementById("empty-msg");
  var totalEl = document.getElementById("total");
  var catTotalsEl = document.getElementById("cat-totals");

  var expenses = load();
  var nextId = expenses.reduce(function (m, e) { return Math.max(m, e.id); }, 0) + 1;

  function load() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (!raw) return [];
      var parsed = JSON.parse(raw);
      if (!Array.isArray(parsed)) return [];
      return parsed
        .filter(function (e) {
          return e && typeof e === "object" && isFinite(Number(e.amount)) && Number(e.amount) > 0 && e.date;
        })
        .map(function (e, i) {
          return {
            id: Number(e.id) > 0 ? Number(e.id) : i + 1,
            amount: Number(e.amount),
            category: CATEGORIES.indexOf(e.category) >= 0 ? e.category : "fun",
            date: String(e.date),
            note: e.note ? String(e.note) : ""
          };
        });
    } catch (err) {
      return [];
    }
  }

  function save() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (err) { /* storage unavailable — app still works in-memory */ }
  }

  function money(n) {
    return (Math.round(n * 100) / 100).toFixed(2);
  }

  // Sort newest first: by date, then by insertion id for same-day entries.
  function sorted() {
    return expenses.slice().sort(function (a, b) {
      if (a.date === b.date) return b.id - a.id;
      return a.date < b.date ? 1 : -1;
    });
  }

  function isVisible(exp) {
    var cat = filterCatEl.value;
    if (cat !== "all" && exp.category !== cat) return false;
    var from = filterFromEl.value;
    var to = filterToEl.value;
    if (from && exp.date < from) return false;
    if (to && exp.date > to) return false;
    return true;
  }

  function render() {
    listEl.textContent = "";
    var rows = sorted();
    var visibleCount = 0;
    var total = 0;
    var catSums = {};
    CATEGORIES.forEach(function (c) { catSums[c] = 0; });

    rows.forEach(function (exp) {
      var tr = document.createElement("tr");
      tr.className = "expense";
      tr.setAttribute("data-id", String(exp.id));
      tr.setAttribute("data-category", exp.category);
      tr.setAttribute("data-date", exp.date);

      var tdAmt = document.createElement("td");
      tdAmt.className = "amt";
      tdAmt.textContent = money(exp.amount);
      tr.appendChild(tdAmt);

      var tdCat = document.createElement("td");
      var span = document.createElement("span");
      span.className = "cat";
      span.textContent = exp.category;
      tdCat.appendChild(span);
      tr.appendChild(tdCat);

      var tdDate = document.createElement("td");
      tdDate.textContent = exp.date;
      tr.appendChild(tdDate);

      var tdNote = document.createElement("td");
      tdNote.className = "note";
      tdNote.textContent = exp.note;
      tr.appendChild(tdNote);

      var tdDel = document.createElement("td");
      var btn = document.createElement("button");
      btn.type = "button";
      btn.className = "exp-del";
      btn.textContent = "Delete";
      btn.setAttribute("aria-label", "Delete expense");
      btn.setAttribute("data-id", String(exp.id));
      tdDel.appendChild(btn);
      tr.appendChild(tdDel);

      if (isVisible(exp)) {
        visibleCount++;
        total += exp.amount;
        if (catSums.hasOwnProperty(exp.category)) catSums[exp.category] += exp.amount;
      } else {
        tr.hidden = true;
        tr.style.display = "none";
      }

      listEl.appendChild(tr);
    });

    totalEl.textContent = money(total);
    emptyEl.hidden = visibleCount !== 0;

    catTotalsEl.textContent = "";
    CATEGORIES.forEach(function (c) {
      var div = document.createElement("div");
      div.className = "cat-total";
      div.setAttribute("data-cat", c);
      div.textContent = c + ": " + money(catSums[c]);
      catTotalsEl.appendChild(div);
    });
  }

  form.addEventListener("submit", function (ev) {
    ev.preventDefault();

    var rawAmount = String(amountEl.value).trim();
    var amount = Number(rawAmount);
    var date = dateEl.value;

    if (rawAmount === "" || !isFinite(amount) || isNaN(amount)) {
      errorEl.textContent = "Please enter a valid numeric amount.";
      return;
    }
    if (amount <= 0) {
      errorEl.textContent = "Amount must be greater than zero.";
      return;
    }
    if (!date) {
      errorEl.textContent = "Please pick a date.";
      return;
    }

    expenses.push({
      id: nextId++,
      amount: amount,
      category: categoryEl.value,
      date: date,
      note: noteEl.value.trim()
    });

    errorEl.textContent = "";
    amountEl.value = "";
    noteEl.value = "";
    save();
    render();
    amountEl.focus();
  });

  listEl.addEventListener("click", function (ev) {
    var btn = ev.target.closest ? ev.target.closest(".exp-del") : null;
    if (!btn) return;
    var id = Number(btn.getAttribute("data-id"));
    expenses = expenses.filter(function (e) { return e.id !== id; });
    save();
    render();
  });

  [filterCatEl, filterFromEl, filterToEl].forEach(function (el) {
    el.addEventListener("change", render);
    el.addEventListener("input", render);
  });

  clearFiltersEl.addEventListener("click", function () {
    filterCatEl.value = "all";
    filterFromEl.value = "";
    filterToEl.value = "";
    render();
  });

  // Default the entry date to today for convenience.
  (function setToday() {
    var d = new Date();
    var pad = function (n) { return (n < 10 ? "0" : "") + n; };
    dateEl.value = d.getFullYear() + "-" + pad(d.getMonth() + 1) + "-" + pad(d.getDate());
  })();

  render();
})();
</script>
</body>
</html>
